function applyGlassMaterial(){preferences=glassAppearance.normalize(preferences);const liquid=preferences.interfaceStyle==='liquid';document.body.classList.toggle('liquid-ui',liquid);document.body.dataset.interfaceStyle=preferences.interfaceStyle;const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;document.body.dataset.glassMotion=preferences.glassMotion&&!reduced?'on':'off';const dark=document.body.dataset.theme!=='day',mat=glassAppearance.material(preferences,dark);for(const[k,v]of Object.entries({'--glass-blur':mat.frost+'px','--glass-fill-alpha':String(mat.fill),'--glass-pane-alpha':String(Math.min(.72,mat.fill*.82)),'--glass-base-veil':String(mat.veil)}))document.body.style.setProperty(k,v);const opticsKey=[liquid,preferences.backgroundMode,preferences.glassFrost,preferences.glassRefraction,preferences.glassMotion,reduced].join(':');if(opticsKey!==glassOpticsKey){glassOpticsKey=opticsKey;clearTimeout(glassOpticsTimer);glassOpticsTimer=setTimeout(()=>syncGlassOptics(mat.lens),65)}window.YingjiLiquidGlass?.configure({enabled:liquid,frost:preferences.glassFrost,white:preferences.glassWhiteness,refraction:preferences.glassRefraction,magnification:preferences.glassMagnification,motion:preferences.glassMotion&&!reduced,dark});updateGlassControls();scheduleGlassSurfaces()}
applyPreferences=function(){baseApplyPreferences();applyGlassMaterial()};
function syncGlassOptics(opts){if(window.YingjiLiquidGlass){glassWatcher?.stop();glassWatcher=null;return}if(!window.Hyalite)return;if(preferences.interfaceStyle!=='liquid'||preferences.runtimeTransparent===true){glassWatcher?.stop();glassWatcher=null;return}if(!Hyalite.supported())return;opts={...opts,materialize:document.body.dataset.glassMotion==='on'?140:0};if(!glassWatcher)glassWatcher=Hyalite.watch(document.body,'.glass-refractor',opts);glassOpticsPromise=Hyalite.setOpts(opts)}
