function syncGlassSurfaces(){const liquid=preferences.interfaceStyle==='liquid';const candidates=document.querySelectorAll('.sidebar,.catalog-toolbar,.sidebar-nav button,.page-title-actions .button.secondary,.glass-preview-tile');for(const el of candidates){const wanted=liquid&&!window.YingjiLiquidGlass&&preferences.runtimeTransparent!==true&&!el.matches('.sidebar-nav button');if(el.classList.contains('glass-refractor')!==wanted)el.classList.toggle('glass-refractor',wanted);if(el.matches('button')&&!el.classList.contains('glass-tactile'))el.classList.add('glass-tactile')}document.querySelectorAll('.liquid-icon').forEach(el=>el.setAttribute('stroke-linecap','round'));if(state.tab==='catalog'){const title=$('#main .heading-row h1');if(liquid&&title&&!title.querySelector('em'))title.innerHTML='总有一个故事，<em>值得相遇。</em>'}}
