function installGlassSettings(){if($('#glassSettings'))return;const panel=document.createElement('section');panel.className='glass-settings';panel.id='glassSettings';panel.setAttribute('aria-label','液态玻璃外观设置');panel.innerHTML=`<div class="glass-settings-header"><div class="glass-settings-title">${svg('glass')}<div><h3>玻璃质感，随心调配。</h3><p>把界面调成你喜欢的清透与柔雾。</p></div></div><div class="glass-style-switch" role="group" aria-label="界面风格"><button data-glass-style="liquid">液态玻璃</button><button data-glass-style="classic">简约经典</button></div></div><div class="glass-settings-layout"><div class="glass-material-preview" aria-label="实时玻璃材质预览"><div class="glass-preview-ring"></div><div class="glass-preview-line"></div><div class="glass-preview-tile">${svg('sparkle')}<strong>映迹</strong><span>LIQUID STORIES</span></div></div><div><div class="glass-slider-row"><div class="glass-slider-label"><label for="glassFrost">面板磨砂强度</label><output id="glassFrostValue" for="glassFrost"></output></div><input id="glassFrost" type="range" min="0" max="40" step="1" aria-label="玻璃磨砂强度"><small>从清透到柔雾，只柔化玻璃后的背景，文字保持清晰。</small></div><div class="glass-slider-row"><div class="glass-slider-label"><label for="glassWhiteness">白色底色浓度</label><output id="glassWhiteValue" for="glassWhiteness"></output></div><input id="glassWhiteness" type="range" min="0" max="100" step="1" aria-label="玻璃白色底色浓度"><small>越高越偏乳白，越低越能透出背景色彩；适配当前主题。</small></div><div class="glass-slider-row glass-refraction-slider"><div class="glass-slider-label"><label for="glassRefraction">边缘折射</label><output id="glassRefractionValue" for="glassRefraction"></output></div><input id="glassRefraction" type="range" min="0" max="100" step="1" aria-label="玻璃边缘折射强度"><small>调整玻璃边缘的弯曲与细微色散，文字保持清晰。</small></div><div class="glass-slider-row"><div class="glass-slider-label"><label for="glassMagnification">透镜放大</label><output id="glassMagnificationValue"></output></div><input id="glassMagnification" type="range" min="100" max="115" step="1" aria-label="玻璃背景放大程度"><small>只放大玻璃后的软件内容，文字和封面控件保持原尺寸。</small></div><div class="glass-presets"><span>材质预设</span><button data-glass-preset="demo">Demo 质感</button><button data-glass-preset="clear">清透</button><button data-glass-preset="soft">柔雾</button><button data-glass-preset="milk">乳白</button></div></div></div><div class="glass-settings-foot"><label class="glass-motion-option"><input id="glassMotion" type="checkbox">柔和交互动效</label><span id="glassSaveState" role="status">设置会自动保存在本机</span><button class="glass-reset" data-glass-reset>恢复默认质感</button></div><p class="rdev-engine-note">面板磨砂、透镜放大和边缘汇光实时作用于软件内的背景。桌面模式另由 Windows 柔化窗外内容；使用自己的背景图片能更清楚地看到折射。</p>`;const columns=$('#main .settings-columns');if(columns)columns.before(panel);else $('#main').append(panel);updateGlassControls()}
const glassPresets={demo:{glassFrost:20,glassWhiteness:38,glassRefraction:50,backgroundMode:'art',glassMotion:true},clear:{glassFrost:5,glassWhiteness:16},soft:{glassFrost:18,glassWhiteness:38},milk:{glassFrost:30,glassWhiteness:78}};
function updateGlassControls(){if(!$('#glassSettings'))return;for(const [key,value]of [['glassFrost',preferences.glassFrost],['glassWhiteness',preferences.glassWhiteness],['glassRefraction',preferences.glassRefraction],['glassMagnification',preferences.glassMagnification]]){const input=$('#'+key);if(input){input.value=String(value);input.disabled=false}}const desktop=preferences.backgroundMode==='desktop';$('#glassFrostValue').textContent=preferences.glassFrost+' px';$('#glassWhiteValue').textContent=preferences.glassWhiteness+'%';$('#glassRefractionValue').textContent=preferences.glassRefraction+'%';if($('#glassMagnificationValue'))$('#glassMagnificationValue').textContent=preferences.glassMagnification+'%';$('#glassFrost').parentElement.querySelector('small').textContent=desktop?'控制详情等应用内玻璃面板；窗外桌面的磨砂仍由 Windows 控制。':'实时柔化玻璃后的背景；文字和操作保持清晰。';$('#glassRefraction').parentElement.querySelector('small').textContent='控制应用内背景在玻璃边缘的弯曲与汇光。';if($('#glassMotion'))$('#glassMotion').checked=preferences.glassMotion;document.querySelectorAll('[data-glass-style]').forEach(b=>{const active=b.dataset.glassStyle===preferences.interfaceStyle;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active))});document.querySelectorAll('[data-glass-preset]').forEach(b=>{const p=glassPresets[b.dataset.glassPreset];b.classList.toggle('active',p.glassFrost===preferences.glassFrost&&p.glassWhiteness===preferences.glassWhiteness)})}
function adjustGlass(patch,immediate=false){preferences=glassAppearance.normalize({...preferences,...patch});glassRevision++;applyPreferences();if($('#glassSaveState'))$('#glassSaveState').textContent='正在保存外观…';clearTimeout(glassSaveTimer);if(immediate)persistGlassSettings();else glassSaveTimer=setTimeout(persistGlassSettings,240)}
function persistGlassSettings(){clearTimeout(glassSaveTimer);glassSaveTimer=0;const revision=glassRevision,snapshot={...preferences};glassSaveChain=glassSaveChain.catch(()=>{}).then(async()=>{try{const saved=await invoke('setPreferences',snapshot);if(revision===glassRevision){preferences=glassAppearance.normalize({...preferences,...saved});windowNeedsRestart=!!saved.requiresRestart;applyPreferences();const actions=$('.wallpaper-actions');if(actions&&windowNeedsRestart&&!actions.querySelector('[data-restart-app]'))actions.insertAdjacentHTML('beforeend','<button class="action-pill done" data-restart-app>应用并重启窗口</button>');if(!windowNeedsRestart)actions?.querySelector('[data-restart-app]')?.remove();if($('#glassSaveState'))$('#glassSaveState').textContent='外观已保存，下次打开自动恢复'}}catch(e){if($('#glassSaveState'))$('#glassSaveState').textContent='尚未写入本机，请重试';toast(e.message)}});return glassSaveChain}
document.addEventListener('input',e=>{if(e.target.id==='glassMagnification')adjustGlass({glassMagnification:Number(e.target.value)});if(e.target.id==='glassFrost')adjustGlass({glassFrost:Number(e.target.value)});if(e.target.id==='glassWhiteness')adjustGlass({glassWhiteness:Number(e.target.value)});if(e.target.id==='glassRefraction')adjustGlass({glassRefraction:Number(e.target.value)})});
document.addEventListener('change',e=>{if(e.target.id==='glassFrost'||e.target.id==='glassWhiteness'||e.target.id==='glassRefraction'||e.target.id==='glassMagnification')persistGlassSettings();if(e.target.id==='glassMotion')adjustGlass({glassMotion:e.target.checked},true)});
document.addEventListener('click',e=>{const preset=e.target.closest('[data-glass-preset]');if(preset){e.preventDefault();adjustGlass(glassPresets[preset.dataset.glassPreset],true);if(preset.dataset.glassPreset==='demo'&&state.tab==='settings')renderSettings()}const style=e.target.closest('[data-glass-style]');if(style){e.preventDefault();adjustGlass({interfaceStyle:style.dataset.glassStyle},true)}if(e.target.closest('[data-glass-reset]')){e.preventDefault();adjustGlass({...glassAppearance.DEFAULTS},true)}});
let glassPointerFrame=0,glassPointerEvent=null,glassPressed=null;
document.addEventListener('pointermove',e=>{if(preferences.interfaceStyle!=='liquid'||document.body.dataset.glassMotion!=='on')return;glassPointerEvent=e;if(glassPointerFrame)return;glassPointerFrame=requestAnimationFrame(()=>{glassPointerFrame=0;const event=glassPointerEvent,target=event.target.closest('.glass-tactile');if(!target)return;const r=target.getBoundingClientRect();target.style.setProperty('--pointer-x',((event.clientX-r.left)/r.width*100).toFixed(1)+'%');target.style.setProperty('--pointer-y',((event.clientY-r.top)/r.height*100).toFixed(1)+'%')})},{passive:true});
