window.YingjiGlass={getState:()=>({preferences:{interfaceStyle:preferences.interfaceStyle,glassFrost:preferences.glassFrost,glassWhiteness:preferences.glassWhiteness,glassRefraction:preferences.glassRefraction,glassMotion:preferences.glassMotion},supported:!!window.YingjiLiquidGlass&&CSS.supports('backdrop-filter','blur(1px)'),engine:window.YingjiLiquidGlass?'liquid-glass-react@'+YingjiLiquidGlass.version:'fallback',lenses:window.YingjiLiquidGlass?.surfaceCount()||0}),flush:async()=>{if(glassSaveTimer)await persistGlassSettings();await glassSaveChain;await glassOpticsPromise}};
